from decimal import Decimal, ROUND_HALF_UP

def dollars_to_cents(dollars: float) -> int:
    decimal_value = Decimal(str(dollars))
    cents = decimal_value * 100
    return int(cents.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
